describe('Page Title Update on Section Navigation', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should update page title when navigating between sections', () => {
    // Verify initial page title
    cy.title().should('include', 'Home');

    // Navigate to About section
    cy.get('[data-testid="nav-about-button"]').click();

    // Verify page title updates to About
    cy.title().should('include', 'About Us');

    // Navigate to Contact section
    cy.get('[data-testid="nav-contact-button"]').click();

    // Verify page title updates to Contact
    cy.title().should('include', 'Contact');

    // Navigate back to Home section
    cy.get('[data-testid="nav-home-button"]').click();

    // Verify page title updates back to Home
    cy.title().should('include', 'Home');
  });

  it('should handle navigation with invalid section links gracefully', () => {
    // Verify initial page title
    cy.title().should('include', 'Home');

    // Attempt to navigate to a non-existent section
    cy.get('[data-testid="nav-invalid-button"]').click();

    // Verify page title does not change or shows error state
    cy.title().should('include', 'Home');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Section not found');

    // Verify navigation buttons are still functional
    cy.get('[data-testid="nav-about-button"]').click();
    cy.title().should('include', 'About Us');

    // Verify error message is cleared
    cy.get('[data-testid="error-message"]').should('not.exist');
  });
});
